function containsIdentifier(text: string, identifier: string): boolean {
  if (identifier.length === 0) return false
  const escaped = identifier.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  return new RegExp(`\\b${escaped}\\b`).test(text)
}

